VALUES ('doc-09-mitre-attack-p0-24455', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-29T18:06:39.265Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mini Shai-Hulud](https://attack.mitre.org/software/S9043) has the ability to check system details for its language configuration and terminates actions when the system is configured for the Russian language.(Citation: Wiz Mini Shai-Hulud MAY 2026)(Citation: Phoenix TeamPCP 20 MAY 2026)", "external_references": [{"description": "McCarthy, R., Cohen, A., and Read, B. (2026, May 12). Mini Shai-Hulud Strikes Again: TanStack + more npm Packages Compromised. Retrieved July 16, 2026.", "source_name": "Wiz Mini Shai-Hulud MAY 2026", "url": "https://www.wiz.io/blog/mini-shai-hulud-strikes-again-tanstack-more-npm-packages-compromised"}, {"description": "Webb, M. (2026, May 20). TeamPCP Wave Four: GitHub Breach via Poisoned VS Code Extension, durabletask PyPI Worm, and ~4,000 Internal Repositories Exfiltrated. Retrieved July 16, 2026.", "source_name": "Phoenix TeamPCP 20 MAY 2026", "url": "https://phoenix.security/teampcp-github-breach-durabletask-pypi-supply-chain-wave-four-2026/"}], "id": "relationship--5c316caa-ecd9-4185-bd42-16b16343d405", "modified": "2026-07-29T20:41:28.009Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--7f211b2e-c008-4cac-9ea8-29bd7edd50a4", "spec_version": "2.1", "target_ref": "attack-pattern--c1b68a96-3c48-49ea-a6c0-9b27359f9c19", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24455', 0, 134, '09-mitre-attack', 'retrieved', '86ACCC2409F4FC17A85E249DBA9F50C88FA21CAF17D8A7EB8AB6CDB3A90E4A5F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
