VALUES ('doc-09-mitre-attack-p0-24456', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-29T18:05:34.720Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mini Shai-Hulud](https://attack.mitre.org/software/S9043) has utilized execution guardrails in order to prevent operating in restricted geolocations to include Russia by checking the devices language and terminating when a forbidden value is detected.(Citation: Wiz Mini Shai-Hulud MAY 2026)(Citation: Phoenix TeamPCP 20 MAY 2026) [Mini Shai-Hulud](https://attack.mitre.org/software/S9043) has also utilized designated instructions that execute when victim hosts match geolocations to include wiping victim devices when the device is determined to be located within Iran or Israel.(Citation: Hunt.io TeamPCP Toolkit MAY 2026)", "external_references": [{"description": "Hunt.io. (2026, May 14). How TeamPCP''s Python Toolkit Survives a C2 Takedown: FIRESCALE, GitHub, and the Victim''s Own Account. Retrieved July 16, 2026.", "source_name": "Hunt.io TeamPCP Toolkit MAY 2026", "url": "https://hunt.io/blog/teampcp-python-toolkit-firescale-github-c2-takedown"}, {"description": "McCarthy, R., Cohen, A., and Read, B. (2026, May 12). Mini Shai-Hulud Strikes Again: TanStack + more npm Packages Compromised. Retrieved July 16, 2026.", "source_name": "Wiz Mini Shai-Hulud MAY 2026", "url": "https://www.wiz.io/blog/mini-shai-hulud-strikes-again-tanstack-more-npm-packages-compromised"}, {"description": "Webb, M. (2026, May 20). TeamPCP Wave Four: GitHub Breach via Poisoned VS Code Extension, durabletask PyPI Worm, and ~4,000 Internal Repositories Exfiltrated. Retrieved July 16, 2026.", "source_name": "Phoenix TeamPCP 20 MAY 2026", "url": "https://phoenix.security/teampcp-github-breach-durabletask-pypi-supply-chain-wave-four-2026/"}], "id": "relationship--e9d29d73-6a2e-4b06-81e0-4dd29467711b", "modified": "2026-07-29T20:42:26.928Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--7f211b2e-c008-4cac-9ea8-29bd7edd50a4", "spec_version": "2.1", "target_ref": "attack-pattern--853c4192-4311-43e1-bfbb-b11b14911852", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24456', 0, 207, '09-mitre-attack', 'retrieved', '8DCC6D74A7E92A189C243827D78E8BDAC32875F51ECD08638DFF226223B1CFEF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
