VALUES ('doc-09-mitre-attack-p0-24463', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-29T20:19:29.724Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mini Shai-Hulud](https://attack.mitre.org/software/S9043) has queried the system timezone configuration and timezone data files to include `/etc/localtime`, and locale settings to determine the geolocation of the compromised host.(Citation: Hunt.io TeamPCP Toolkit MAY 2026)(Citation: Phoenix TeamPCP 20 MAY 2026)", "external_references": [{"description": "Hunt.io. (2026, May 14). How TeamPCP''s Python Toolkit Survives a C2 Takedown: FIRESCALE, GitHub, and the Victim''s Own Account. Retrieved July 16, 2026.", "source_name": "Hunt.io TeamPCP Toolkit MAY 2026", "url": "https://hunt.io/blog/teampcp-python-toolkit-firescale-github-c2-takedown"}, {"description": "Webb, M. (2026, May 20). TeamPCP Wave Four: GitHub Breach via Poisoned VS Code Extension, durabletask PyPI Worm, and ~4,000 Internal Repositories Exfiltrated. Retrieved July 16, 2026.", "source_name": "Phoenix TeamPCP 20 MAY 2026", "url": "https://phoenix.security/teampcp-github-breach-durabletask-pypi-supply-chain-wave-four-2026/"}], "id": "relationship--6308284a-ac28-4943-b15f-368da34c01aa", "modified": "2026-07-29T21:02:47.394Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--7f211b2e-c008-4cac-9ea8-29bd7edd50a4", "spec_version": "2.1", "target_ref": "attack-pattern--f3c544dc-673c-4ef3-accb-53229f1ae077", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24463', 0, 134, '09-mitre-attack', 'retrieved', '0EE787D53256D29E2168C566A24482D81B8E244D1429A1C1A3B60A681281D643', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1