VALUES ('doc-09-mitre-attack-p0-24466', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-29T19:02:07.263Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mini Shai-Hulud](https://attack.mitre.org/software/S9043) has used a hybrid AES-256-GCM and RSA OAEP-SHA256 encryption to archive gathered data. [Mini Shai-Hulud](https://attack.mitre.org/software/S9043) has also utilized custom MD5-keystream XOR cipher to encrypt data.(Citation: Trend Micro TeamPCP MAY 2026) [Mini Shai-Hulud](https://attack.mitre.org/software/S9043) has also been deployed via an obfuscated script using Bun JavaScript runtime.(Citation: Flashpoint Mini Shai-Hulud MAY 2026)", "external_references": [{"description": "Flashpoint. (2026, May 28). The Mini Shai-Hulud Worm and the New Era of CI/CD Exploitation. Retrieved July 16, 2026.", "source_name": "Flashpoint Mini Shai-Hulud MAY 2026", "url": "https://flashpoint.io/blog/mini-shai-hulud-worm-new-era-ci-cd-exploitation/"}, {"description": "Santos, J. and Navato, J.R. (2026, May 13). Analyzing TeamPCP’s Supply Chain Attacks: Checkmarx KICS and elementary-data in CI/CD Credential Theft. Retrieved July 16, 2026.", "source_name": "Trend Micro TeamPCP MAY 2026", "url": "https://www.trendmicro.com/en_us/research/26/e/analyzing-teampcp-supply-chain-attacks.html"}], "id": "relationship--ae6af46e-ac3d-40dd-8733-0f5f8429b5ef", "modified": "2026-07-29T21:10:31.516Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--7f211b2e-c008-4cac-9ea8-29bd7edd50a4", "spec_version": "2.1", "target_ref": "attack-pattern--0d91b3c0-5e50-47c3-949a-2a796f04d144", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24466', 0, 143, '09-mitre-attack', 'retrieved', 'CFBA781B09D609