VALUES ('doc-09-mitre-attack-p0-24478', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-29T17:54:57.396Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mini Shai-Hulud](https://attack.mitre.org/software/S9043) has leveraged GitHub commit-search API to recover fallback C2 domains stored in auto-created public Github repositories.(Citation: Wiz Mini Shai-Hulud MAY 2026)(Citation: Trend Micro TeamPCP MAY 2026)(Citation: Hunt.io TeamPCP Toolkit MAY 2026)(Citation: Phoenix TeamPCP 20 MAY 2026)(Citation: Flashpoint Mini Shai-Hulud MAY 2026)", "external_references": [{"description": "Flashpoint. (2026, May 28). The Mini Shai-Hulud Worm and the New Era of CI/CD Exploitation. Retrieved July 16, 2026.", "source_name": "Flashpoint Mini Shai-Hulud MAY 2026", "url": "https://flashpoint.io/blog/mini-shai-hulud-worm-new-era-ci-cd-exploitation/"}, {"description": "Hunt.io. (2026, May 14). How TeamPCP''s Python Toolkit Survives a C2 Takedown: FIRESCALE, GitHub, and the Victim''s Own Account. Retrieved July 16, 2026.", "source_name": "Hunt.io TeamPCP Toolkit MAY 2026", "url": "https://hunt.io/blog/teampcp-python-toolkit-firescale-github-c2-takedown"}, {"description": "McCarthy, R., Cohen, A., and Read, B. (2026, May 12). Mini Shai-Hulud Strikes Again: TanStack + more npm Packages Compromised. Retrieved July 16, 2026.", "source_name": "Wiz Mini Shai-Hulud MAY 2026", "url": "https://www.wiz.io/blog/mini-shai-hulud-strikes-again-tanstack-more-npm-packages-compromised"}, {"description": "Santos, J. and Navato, J.R. (2026, May 13). Analyzing TeamPCP’s Supply Chain Attacks: Checkmarx KICS and elementary-data in CI/CD Credential Theft. Retrieved July 16, 2026.", "source_name": "Trend Micro TeamPCP MAY 2026", "url": "https://www.trendmicro.com/en_us/research/26/e/analyzing-teampcp-supply-chain-attacks.html"}, {"description": "Webb, M. (2026, May 20). TeamPCP Wave Four: GitHub Breach via Poisoned VS Code Extension, durabletask PyPI Worm, and ~4,000 Internal Repositories Exfiltrated. Retrieved July 16, 2026.", "source_name": "Phoenix TeamPCP 20 MAY 2026", "url": "https://phoenix.security/teampcp-github-breach-durabletask-pypi-supply-chain-wave-four-2026/"}], "id": "relationship--e7e1d905-6777-4299-b7d7-3465d9eac294", "modified": "2026-07-29T21:35:02.297Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--7f211b2e-c008-4cac-9ea8-29bd7edd50a4", "spec_version": "2.1", "target_ref": "attack-pattern--f7827069-0bf2-4764-af4f-23fae0d181b7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24478', 0, 236, '09-mitre-attack', 'retrieved', 'A98FF7F5C98A946C024E8FC9508D24F0B8D2DB2EF026597DF5C85F825166530C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
