VALUES ('doc-09-mitre-attack-p0-24479', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-29T18:00:39.154Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mini Shai-Hulud](https://attack.mitre.org/software/S9043) has obtained persistence on Linux devices by writing the `gh-token-monitor` daemon within `~/.config/systemd/user/gh-token-monitor.service` that polls GitHub every 60 seconds.(Citation: Wiz Mini Shai-Hulud MAY 2026) [Mini Shai-Hulud](https://attack.mitre.org/software/S9043) has also leveraged a daemon called “kitty-monitor.service” to maintain persistence within Linux hosts.(Citation: Flashpoint Mini Shai-Hulud MAY 2026)", "external_references": [{"description": "Flashpoint. (2026, May 28). The Mini Shai-Hulud Worm and the New Era of CI/CD Exploitation. Retrieved July 16, 2026.", "source_name": "Flashpoint Mini Shai-Hulud MAY 2026", "url": "https://flashpoint.io/blog/mini-shai-hulud-worm-new-era-ci-cd-exploitation/"}, {"description": "McCarthy, R., Cohen, A., and Read, B. (2026, May 12). Mini Shai-Hulud Strikes Again: TanStack + more npm Packages Compromised. Retrieved July 16, 2026.", "source_name": "Wiz Mini Shai-Hulud MAY 2026", "url": "https://www.wiz.io/blog/mini-shai-hulud-strikes-again-tanstack-more-npm-packages-compromised"}], "id": "relationship--43130352-f2d9-4a3f-8c9a-8ec46fce38d9", "modified": "2026-07-29T21:36:46.864Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--7f211b2e-c008-4cac-9ea8-29bd7edd50a4", "spec_version": "2.1", "target_ref": "attack-pattern--a542bac9-7bc1-4da7-9a09-96f69e23cc21", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24479', 0, 137, '09-mitre-attack', 'retrieved', 'E64B5F5B973A3E85F1C3175670BD0C2760A1370A2E03697676BD433621825D0B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
