VALUES ('doc-09-mitre-attack-p0-24481', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-29T21:39:50.463Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mini Shai-Hulud](https://attack.mitre.org/software/S9043) has established persistence through modifying software binaries to include AI coding agents’ configuration or setting files that act as hooks, tasks or execution triggers.(Citation: Flashpoint Mini Shai-Hulud MAY 2026)", "external_references": [{"description": "Flashpoint. (2026, May 28). The Mini Shai-Hulud Worm and the New Era of CI/CD Exploitation. Retrieved July 16, 2026.", "source_name": "Flashpoint Mini Shai-Hulud MAY 2026", "url": "https://flashpoint.io/blog/mini-shai-hulud-worm-new-era-ci-cd-exploitation/"}], "id": "relationship--159f5a62-ad01-481e-ba18-a70cd19fa40d", "modified": "2026-07-29T21:39:50.463Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--7f211b2e-c008-4cac-9ea8-29bd7edd50a4", "spec_version": "2.1", "target_ref": "attack-pattern--960c3c86-1480-4d72-b4e0-8c242e84a5c5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24481', 0, 89, '09-mitre-attack', 'retrieved', 'FA6A36F395CB1A946501EF1D616B26E461CEBE0F7D9838BF9E42AD2296680C3E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
