VALUES ('doc-09-mitre-attack-p0-24483', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-29T19:21:52.462Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mini Shai-Hulud](https://attack.mitre.org/software/S9043) has utilized container administration commands to gather details of compromised hosts and gather credentials to include Kubernetes command-line utilities `kubectl get secrets`.(Citation: Trend Micro TeamPCP MAY 2026)(Citation: Phoenix TeamPCP 20 MAY 2026)", "external_references": [{"description": "Santos, J. and Navato, J.R. (2026, May 13). Analyzing TeamPCP’s Supply Chain Attacks: Checkmarx KICS and elementary-data in CI/CD Credential Theft. Retrieved July 16, 2026.", "source_name": "Trend Micro TeamPCP MAY 2026", "url": "https://www.trendmicro.com/en_us/research/26/e/analyzing-teampcp-supply-chain-attacks.html"}, {"description": "Webb, M. (2026, May 20). TeamPCP Wave Four: GitHub Breach via Poisoned VS Code Extension, durabletask PyPI Worm, and ~4,000 Internal Repositories Exfiltrated. Retrieved July 16, 2026.", "source_name": "Phoenix TeamPCP 20 MAY 2026", "url": "https://phoenix.security/teampcp-github-breach-durabletask-pypi-supply-chain-wave-four-2026/"}], "id": "relationship--af573ba3-42c6-497b-8d1c-063a159a4eee", "modified": "2026-07-30T00:25:51.172Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--7f211b2e-c008-4cac-9ea8-29bd7edd50a4", "spec_version": "2.1", "target_ref": "attack-pattern--7b50a1d3-4ca7-45d1-989d-a6503f04bfe1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24483', 0, 134, '09-mitre-attack', 'retrieved', '9A7C74587C22263C1A9CD84CD245261414F7403B24796F527AC9A4214819F13D', 'v1', '{"source_id": "09-mitre-attack", "version": "