VALUES ('doc-09-mitre-attack-p0-24485', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-29T19:16:52.079Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mini Shai-Hulud](https://attack.mitre.org/software/S9043) has executed via the use of `subprocess.run` and fed input through standard input `stdin` which acted as a pipe to send data from the parent process and the child process `sys.executable` within memory.(Citation: Trend Micro TeamPCP MAY 2026)(Citation: Hunt.io TeamPCP Toolkit MAY 2026)", "external_references": [{"description": "Hunt.io. (2026, May 14). How TeamPCP''s Python Toolkit Survives a C2 Takedown: FIRESCALE, GitHub, and the Victim''s Own Account. Retrieved July 16, 2026.", "source_name": "Hunt.io TeamPCP Toolkit MAY 2026", "url": "https://hunt.io/blog/teampcp-python-toolkit-firescale-github-c2-takedown"}, {"description": "Santos, J. and Navato, J.R. (2026, May 13). Analyzing TeamPCP’s Supply Chain Attacks: Checkmarx KICS and elementary-data in CI/CD Credential Theft. Retrieved July 16, 2026.", "source_name": "Trend Micro TeamPCP MAY 2026", "url": "https://www.trendmicro.com/en_us/research/26/e/analyzing-teampcp-supply-chain-attacks.html"}], "id": "relationship--d3e1a3fd-c00a-47b5-9a51-29546f6519e3", "modified": "2026-07-30T00:29:53.569Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--7f211b2e-c008-4cac-9ea8-29bd7edd50a4", "spec_version": "2.1", "target_ref": "attack-pattern--acd0ba37-7ba9-4cc5-ac61-796586cd856d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24485', 0, 141, '09-mitre-attack', 'retrieved', 'BBA0F119C077C6D66CF92976E32FE52B8590073255728F835CF23474D3F8C501', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
