VALUES ('doc-09-mitre-attack-p0-24499', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-24T18:34:59.669Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CanisterWorm](https://attack.mitre.org/software/S9042) has checked if the current user is root. If it is, [CanisterWorm](https://attack.mitre.org/software/S9042) will wipe the system using `rm –rf / --no-preserve-root`. If it is not, [CanisterWorm](https://attack.mitre.org/software/S9042) will try passwordless sudo and will run the same command.(Citation: Aikido CanisterWorm MAR 2026)", "external_references": [{"description": "Eriksen, C. (2026, March 22). CanisterWorm Gets Teeth: TeamPCP''s Kubernetes Wiper Targets Iran. Retrieved July 27, 2026.", "source_name": "Aikido CanisterWorm MAR 2026", "url": "https://www.aikido.dev/blog/teampcp-stage-payload-canisterworm-iran"}], "id": "relationship--fb432b6e-dfa2-4974-92f9-b1c6c8058835", "modified": "2026-07-27T19:37:42.999Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5b30f717-1d7b-4e91-a97d-be361d00aa5e", "spec_version": "2.1", "target_ref": "attack-pattern--1365fe3b-0f50-455d-b4da-266ce31c23b0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24499', 0, 96, '09-mitre-attack', 'retrieved', '50DF276EB66EE456B2A7674286046BCAEC1176DCE8C1BE8FA9838FA93F69484E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
