VALUES ('doc-09-mitre-attack-p0-24515', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-24T18:25:24.815Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CanisterWorm](https://attack.mitre.org/software/S9042) has downloaded and executed binaries from dead drop URLs retrieved from ICP canister C2 nodes.(Citation: Aikido CanisterWorm MAR 2026)(Citation: Aikido TeamPCP Trivy MAR 2026) [CanisterWorm](https://attack.mitre.org/software/S9042) has also downloaded kubectl to compromised environments if it was not already installed.(Citation: Aikido CanisterWorm MAR 2026)", "external_references": [{"description": "Eriksen, C. (2026, March 20). TeamPCP deploys CanisterWorm on NPM following Trivy compromise. Retrieved July 27, 2026.", "source_name": "Aikido TeamPCP Trivy MAR 2026", "url": "https://www.aikido.dev/blog/teampcp-deploys-worm-npm-trivy-compromise"}, {"description": "Eriksen, C. (2026, March 22). CanisterWorm Gets Teeth: TeamPCP''s Kubernetes Wiper Targets Iran. Retrieved July 27, 2026.", "source_name": "Aikido CanisterWorm MAR 2026", "url": "https://www.aikido.dev/blog/teampcp-stage-payload-canisterworm-iran"}], "id": "relationship--3a4f7d04-6c45-4a96-9ce7-bd951d350a1f", "modified": "2026-07-28T16:23:26.026Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5b30f717-1d7b-4e91-a97d-be361d00aa5e", "spec_version": "2.1", "target_ref": "attack-pattern--e6919abc-99f9-4c6c-95a5-14761e7b2add", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24515', 0, 124, '09-mitre-attack', 'retrieved', '6776B2909FD7E33D4BC22D60990ED7BF1A1F9D078AC04960C02E298C2BDD1718', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
