VALUES ('doc-09-mitre-attack-p0-24516', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-24T18:42:26.726Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CanisterWorm](https://attack.mitre.org/software/S9042) has leveraged a Sleep setting of five minutes before executing tasks to evade sandbox environments.(Citation: Aikido TeamPCP Trivy MAR 2026)", "external_references": [{"description": "Eriksen, C. (2026, March 20). TeamPCP deploys CanisterWorm on NPM following Trivy compromise. Retrieved July 27, 2026.", "source_name": "Aikido TeamPCP Trivy MAR 2026", "url": "https://www.aikido.dev/blog/teampcp-deploys-worm-npm-trivy-compromise"}], "id": "relationship--41744eb6-2c96-4627-b41e-2b23702b8dcb", "modified": "2026-07-28T16:28:37.254Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5b30f717-1d7b-4e91-a97d-be361d00aa5e", "spec_version": "2.1", "target_ref": "attack-pattern--4bed873f-0b7d-41d4-b93a-b6905d1f90b0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24516', 0, 77, '09-mitre-attack', 'retrieved', '6F7D9B7A00F35C20D0930FBD24440832E0C8BFBBAF3019C5F76EAF104BE03219', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
