VALUES ('doc-09-mitre-attack-p0-24517', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-27T19:24:31.837Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CanisterWorm](https://attack.mitre.org/software/S9042) can deploy privileged DaemonSets in Kubernetes clusters for data wiping using kubectl.(Citation: Palo Alto TeamPCP MAR 2026)(Citation: Aikido CanisterWorm MAR 2026)", "external_references": [{"description": "Eriksen, C. (2026, March 22). CanisterWorm Gets Teeth: TeamPCP''s Kubernetes Wiper Targets Iran. Retrieved July 27, 2026.", "source_name": "Aikido CanisterWorm MAR 2026", "url": "https://www.aikido.dev/blog/teampcp-stage-payload-canisterworm-iran"}, {"description": "Unit 42. (2026, March 31). Weaponizing the Protectors: TeamPCP’s Multi-Stage Supply Chain Attack on Security Infrastructure. Retrieved July 1, 2026.", "source_name": "Palo Alto TeamPCP MAR 2026", "url": "https://unit42.paloaltonetworks.com/teampcp-supply-chain-attacks/"}], "id": "relationship--7529023c-bf57-4cdc-9ccb-d6e56d29e081", "modified": "2026-07-28T17:26:37.243Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5b30f717-1d7b-4e91-a97d-be361d00aa5e", "spec_version": "2.1", "target_ref": "attack-pattern--7b50a1d3-4ca7-45d1-989d-a6503f04bfe1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24517', 0, 106, '09-mitre-attack', 'retrieved', '2FB0A4918C0E88004879298F5F108BDF6434BEA68444BD95169E4228F67C497D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
