VALUES ('doc-09-mitre-attack-p0-24518', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-24T18:23:57.719Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CanisterWorm](https://attack.mitre.org/software/S9042) has performed environment fingerprinting to identify Kubernetes clusters.(Citation: Palo Alto TeamPCP MAR 2026) [CanisterWorm](https://attack.mitre.org/software/S9042) has also searched for Kubernetes pods using the command ` os.path.exists(\"/var/run/secrets/kubernetes.io/serviceaccount\") or \"KUBERNETES_SERVICE_HOST\" in os.environ `.(Citation: Aikido CanisterWorm MAR 2026)", "external_references": [{"description": "Eriksen, C. (2026, March 22). CanisterWorm Gets Teeth: TeamPCP''s Kubernetes Wiper Targets Iran. Retrieved July 27, 2026.", "source_name": "Aikido CanisterWorm MAR 2026", "url": "https://www.aikido.dev/blog/teampcp-stage-payload-canisterworm-iran"}, {"description": "Unit 42. (2026, March 31). Weaponizing the Protectors: TeamPCP’s Multi-Stage Supply Chain Attack on Security Infrastructure. Retrieved July 1, 2026.", "source_name": "Palo Alto TeamPCP MAR 2026", "url": "https://unit42.paloaltonetworks.com/teampcp-supply-chain-attacks/"}], "id": "relationship--171a0e7e-7297-4954-83c7-727c45f7a220", "modified": "2026-07-28T17:28:50.135Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5b30f717-1d7b-4e91-a97d-be361d00aa5e", "spec_version": "2.1", "target_ref": "attack-pattern--0470e792-32f8-46b0-a351-652bc35e9336", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24518', 0, 119, '09-mitre-attack', 'retrieved', '05D5FB1F20A4404C69DEBA9D81F44CE6D826010A7DAF3F89806F564E99BC1BD9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
