VALUES ('doc-09-mitre-attack-p0-24519', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-27T20:00:24.641Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CanisterWorm](https://attack.mitre.org/software/S9042) has discovered npm pathways and directories that frequently store .npmrc files to check for _authToken values.(Citation: Aikido TeamPCP Trivy MAR 2026)", "external_references": [{"description": "Eriksen, C. (2026, March 20). TeamPCP deploys CanisterWorm on NPM following Trivy compromise. Retrieved July 27, 2026.", "source_name": "Aikido TeamPCP Trivy MAR 2026", "url": "https://www.aikido.dev/blog/teampcp-deploys-worm-npm-trivy-compromise"}], "id": "relationship--b2b29042-e638-446f-94c6-c7de3711884f", "modified": "2026-07-28T17:58:51.894Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5b30f717-1d7b-4e91-a97d-be361d00aa5e", "spec_version": "2.1", "target_ref": "attack-pattern--7bc57495-ea59-4380-be31-a64af124ef18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24519', 0, 78, '09-mitre-attack', 'retrieved', 'A680203C49D89F555051BE39A82F8A10FC57B91C4059C933E2A6BF23BEE953AD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
