VALUES ('doc-09-mitre-attack-p0-24520', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-24T18:11:47.048Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CanisterWorm](https://attack.mitre.org/software/S9042) has leveraged stolen npm tokens to automate compromise by enumerating all publishable packages in a namespace, bumping versions, and publishing itself across the entire scope.(Citation: Aikido TeamPCP Telnyx MAR 2026)(Citation: Aikido TeamPCP Trivy MAR 2026)", "external_references": [{"description": "Eriksen, C. (2026, March 20). TeamPCP deploys CanisterWorm on NPM following Trivy compromise. Retrieved July 27, 2026.", "source_name": "Aikido TeamPCP Trivy MAR 2026", "url": "https://www.aikido.dev/blog/teampcp-deploys-worm-npm-trivy-compromise"}, {"description": "Eriksen, C. (2026, March 27). Popular telnyx package compromised on PyPI by TeamPCP. Retrieved July 16, 2026.", "source_name": "Aikido TeamPCP Telnyx MAR 2026", "url": "https://www.aikido.dev/blog/telnyx-pypi-compromised-teampcp-canisterworm"}], "id": "relationship--be5c4e29-8196-4605-af4c-03a3b1627097", "modified": "2026-07-28T18:03:33.032Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5b30f717-1d7b-4e91-a97d-be361d00aa5e", "spec_version": "2.1", "target_ref": "attack-pattern--f005e783-57d4-4837-88ad-dbe7faee1c51", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24520', 0, 118, '09-mitre-attack', 'retrieved', 'A2A03E76D9A309A2390E35080284007D9B1ED64A178371D01B15FED5E2145485', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
