VALUES ('doc-09-mitre-attack-p0-24522', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-17T17:44:00.365Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TeamPCP](https://attack.mitre.org/groups/G1056) has hidden malicious payloads in the frame data of WAV audio files.(Citation: Aikido TeamPCP Telnyx MAR 2026)(Citation: Palo Alto TeamPCP MAR 2026)", "external_references": [{"description": "Eriksen, C. (2026, March 27). Popular telnyx package compromised on PyPI by TeamPCP. Retrieved July 16, 2026.", "source_name": "Aikido TeamPCP Telnyx MAR 2026", "url": "https://www.aikido.dev/blog/telnyx-pypi-compromised-teampcp-canisterworm"}, {"description": "Unit 42. (2026, March 31). Weaponizing the Protectors: TeamPCP’s Multi-Stage Supply Chain Attack on Security Infrastructure. Retrieved July 1, 2026.", "source_name": "Palo Alto TeamPCP MAR 2026", "url": "https://unit42.paloaltonetworks.com/teampcp-supply-chain-attacks/"}], "id": "relationship--02438776-1130-4715-83b0-9bd6781bf8c0", "modified": "2026-07-31T18:47:43.295Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--20f26558-e05d-46cf-8847-c2b5a83ee779", "spec_version": "2.1", "target_ref": "attack-pattern--c2e147a9-d1a8-4074-811a-d8789202d916", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24522', 0, 108, '09-mitre-attack', 'retrieved', 'E430F0FA665D79D4AB4230ECBBB30767594B5DFB78C5880D2F84B5373C7CEB2A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
