VALUES ('doc-09-mitre-attack-p0-24523', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-16T21:02:10.009Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TeamPCP](https://attack.mitre.org/groups/G1056) has cloned GitHub commit metadata including the author name, email, committer, and timestamps to use for impostor commits.(Citation: Aqua Security Blog Trivy Compromise APR 2026) [TeamPCP](https://attack.mitre.org/groups/G1056) has also used legitimate file names such as msbuild.exe and ringtone.wav to mask malicious payloads.(Citation: Aikido TeamPCP Telnyx MAR 2026)(Citation: Palo Alto TeamPCP MAR 2026)", "external_references": [{"description": "Aqua Team. (2026, April 1). Update: Ongoing Investigation and Continued Remediation. Retrieved July 1, 2026.", "source_name": "Aqua Security Blog Trivy Compromise APR 2026", "url": "https://www.aquasec.com/blog/trivy-supply-chain-attack-what-you-need-to-know"}, {"description": "Eriksen, C. (2026, March 27). Popular telnyx package compromised on PyPI by TeamPCP. Retrieved July 16, 2026.", "source_name": "Aikido TeamPCP Telnyx MAR 2026", "url": "https://www.aikido.dev/blog/telnyx-pypi-compromised-teampcp-canisterworm"}, {"description": "Unit 42. (2026, March 31). Weaponizing the Protectors: TeamPCP’s Multi-Stage Supply Chain Attack on Security Infrastructure. Retrieved July 1, 2026.", "source_name": "Palo Alto TeamPCP MAR 2026", "url": "https://unit42.paloaltonetworks.com/teampcp-supply-chain-attacks/"}], "id": "relationship--0d50119b-b045-4d30-8ba7-ec1ce2d4be40", "modified": "2026-07-31T18:47:43.313Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--20f26558-e05d-46cf-8847-c2b5a83ee779", "spec_version": "2.1", "target_ref": "attack-pattern--1c4e5d32-1fe9-4116-9d9d-59e3925bd6a2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecat