VALUES ('doc-09-mitre-attack-p0-24553', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-17T16:15:39.703Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TeamPCP](https://attack.mitre.org/groups/G1056) has queried the Kubernetes API for local service account tokens and has used `kubectl` for lateral movement.(Citation: Phoenix TeamPCP 20 MAY 2026)(Citation: Wiz TeamPCP KICS MAR 2026)", "external_references": [{"description": "McCarthy, R., Haughom, J., Read, B. (2026, March 23). KICS GitHub Action Compromised: TeamPCP Strikes Again in Supply Chain Attack. Retrieved July 1, 2026.", "source_name": "Wiz TeamPCP KICS MAR 2026", "url": "https://www.wiz.io/blog/teampcp-attack-kics-github-action"}, {"description": "Webb, M. (2026, May 20). TeamPCP Wave Four: GitHub Breach via Poisoned VS Code Extension, durabletask PyPI Worm, and ~4,000 Internal Repositories Exfiltrated. Retrieved July 16, 2026.", "source_name": "Phoenix TeamPCP 20 MAY 2026", "url": "https://phoenix.security/teampcp-github-breach-durabletask-pypi-supply-chain-wave-four-2026/"}], "id": "relationship--c1504d74-bbb3-42b3-81e5-59edf12895ab", "modified": "2026-07-31T18:47:43.890Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--20f26558-e05d-46cf-8847-c2b5a83ee779", "spec_version": "2.1", "target_ref": "attack-pattern--c283d88f-8c23-4318-9da5-3d50cecad756", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24553', 0, 127, '09-mitre-attack', 'retrieved', '4A6B856D6311C493D4AE3F0B404032D620254E3DE8C1C5D427CF59878BFCEEE2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
