VALUES ('doc-09-mitre-attack-p0-24557', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-16T20:35:04.729Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TeamPCP](https://attack.mitre.org/groups/G1056) has pushed GitHub commits that modified the actions/checkout to reference an imposter commit that downloaded malicious files from attacker-controlled C2 domains.(Citation: Aqua Security Trivy Compromise MAR 2026)", "external_references": [{"description": "Aqua Security . (2026, March 21). Trivy ecosystem supply chain temporarily compromised. Retrieved July 1, 2026.", "source_name": "Aqua Security Trivy Compromise MAR 2026", "url": "https://github.com/aquasecurity/trivy/security/advisories/GHSA-69fq-xp46-6x23"}], "id": "relationship--e7d67335-ceea-4300-ab7c-af493013bbb0", "modified": "2026-07-31T18:47:43.967Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--20f26558-e05d-46cf-8847-c2b5a83ee779", "spec_version": "2.1", "target_ref": "attack-pattern--3ee16395-03f0-4690-a32e-69ce9ada0f9e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24557', 0, 84, '09-mitre-attack', 'retrieved', '5FD51FEDB4798856EF239125CE20651232C454C01816F39049BF0497D0877CC3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
