VALUES ('doc-09-mitre-attack-p0-24560', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-17T15:57:04.558Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TeamPCP](https://attack.mitre.org/groups/G1056) has compromised VS Code and Open VSX IDE extensions.(Citation: Wiz TeamPCP KICS MAR 2026)(Citation: Aikido TeamPCP Telnyx MAR 2026)(Citation: Trend Micro TeamPCP MAY 2026)(Citation: Phoenix TeamPCP 20 MAY 2026)(Citation: Flashpoint Mini Shai-Hulud MAY 2026)", "external_references": [{"description": "Eriksen, C. (2026, March 27). Popular telnyx package compromised on PyPI by TeamPCP. Retrieved July 16, 2026.", "source_name": "Aikido TeamPCP Telnyx MAR 2026", "url": "https://www.aikido.dev/blog/telnyx-pypi-compromised-teampcp-canisterworm"}, {"description": "Flashpoint. (2026, May 28). The Mini Shai-Hulud Worm and the New Era of CI/CD Exploitation. Retrieved July 16, 2026.", "source_name": "Flashpoint Mini Shai-Hulud MAY 2026", "url": "https://flashpoint.io/blog/mini-shai-hulud-worm-new-era-ci-cd-exploitation/"}, {"description": "McCarthy, R., Haughom, J., Read, B. (2026, March 23). KICS GitHub Action Compromised: TeamPCP Strikes Again in Supply Chain Attack. Retrieved July 1, 2026.", "source_name": "Wiz TeamPCP KICS MAR 2026", "url": "https://www.wiz.io/blog/teampcp-attack-kics-github-action"}, {"description": "Santos, J. and Navato, J.R. (2026, May 13). Analyzing TeamPCP’s Supply Chain Attacks: Checkmarx KICS and elementary-data in CI/CD Credential Theft. Retrieved July 16, 2026.", "source_name": "Trend Micro TeamPCP MAY 2026", "url": "https://www.trendmicro.com/en_us/research/26/e/analyzing-teampcp-supply-chain-attacks.html"}, {"description": "Webb, M. (2026, May 20). TeamPCP Wave Four: GitHub Breach via Poisoned VS Code Extension, durabletask PyPI Worm, and ~4,000 Internal Repositories Exfiltrated. Retrieved July 16, 2026.", "source_name": "Phoenix TeamPCP 20 MAY 2026", "url": "https://phoenix.security/teampcp-github-breach-durabletask-pypi-supply-chain-wave-four-2026/"}], "id": "relationship--f4b6ec8f-fa03-4584-929b-649ef3e999b1", "modified": "2026-07-31T18:47:44.028Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--20f26558-e05d-46cf-8847-c2b5a83ee779", "spec_version": "2.1", "target_ref": "attack-pattern--66b34be7-6915-4b83-8d5a-b0f0592b5e41", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24560', 0, 222, '09-mitre-attack', 'retrieved', 'D6F3F2B3271D385A81C152E7FC6B086D668FBE0181E957985197524548354DC3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
