VALUES ('doc-09-mitre-attack-p0-24569', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-29T18:43:17.564Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ShinyHunters](https://attack.mitre.org/groups/G1057) has used the MeshCentral command-line interface utility meshctrl.js and npm to interact with compromised systems. Specifically for npm, [ShinyHunters](https://attack.mitre.org/groups/G1057) has checked for the authenticode tool using the command `npm list global authenticode`.(Citation: Google_SHOracle_Jun2026) Additionally, [ShinyHunters](https://attack.mitre.org/groups/G1057) has used the MeshCentral command to execute the propagation script: ` node meshctrl.js RunCommand --loginuser admin --loginpass ''[password]'' --id ''[agent_id]'' --run ''bash /tmp/[victim_abbreviation]_fanout.sh'' `.(Citation: Google_SHOracle_Jun2026) ", "external_references": [{"description": "Mandiant, Google Threat Intelligence Group. (2026, June 11). ShinyHunters Targets Education Sector with Oracle PeopleSoft Exploit. Retrieved June 11, 2026.", "source_name": "Google_SHOracle_Jun2026", "url": "https://cloud.google.com/blog/topics/threat-intelligence/shinyhunters-targets-education-sector-oracle-exploit"}], "id": "relationship--4677c432-d537-4d61-bc25-efe1b608c378", "modified": "2026-07-31T18:47:58.722Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--5e30362d-935b-4b1c-8bf2-96c7b7b7e299", "spec_version": "2.1", "target_ref": "attack-pattern--0f4a0c76-ab2d-4cb0-85d3-3f0efb8cba0d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24569', 0, 117, '09-mitre-attack', 'retrieved', '6C3A7B2DA713617AD6BC47FE34107E15A4B42CEA749FB26F1E7DD5B9A1248FE4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
