VALUES ('doc-09-mitre-attack-p0-24570', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-29T19:23:52.546Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ShinyHunters](https://attack.mitre.org/groups/G1057) has used valid high-privileged SSO users as leverage during negotiations.(Citation: ElecticIQ Buyukkaya_ShinyHunters_Sept2025) ", "external_references": [{"description": "Büyükkaya, A. (2025, September 22). ShinyHunters Calling: Financially Motivated Data Extortion Group Targeting Enterprise Cloud Applications. Retrieved May 18, 2026.", "source_name": "ElecticIQ Buyukkaya_ShinyHunters_Sept2025", "url": "https://blog.eclecticiq.com/shinyhunters-calling-financially-motivated-data-extortion-group-targeting-enterprise-cloud-applications"}], "id": "relationship--4cbfc615-1e0d-4140-bf36-8b83b6a087d2", "modified": "2026-07-31T18:47:58.735Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--5e30362d-935b-4b1c-8bf2-96c7b7b7e299", "spec_version": "2.1", "target_ref": "attack-pattern--b17a1a56-e99c-403c-8948-561df0cffe81", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24570', 0, 70, '09-mitre-attack', 'retrieved', '8BD0BC29E4502916029A47D0EA16B211799D803F03D3F71D7F0241733B1D0BCF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
