VALUES ('doc-09-mitre-attack-p0-24571', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-29T19:22:44.844Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ShinyHunters](https://attack.mitre.org/groups/G1057) has used compromised Salesforce CRM (Customer Relationship Management) dashboards to exfiltrate bulk data. Additionally, [ShinyHunters](https://attack.mitre.org/groups/G1057) has used LimeWire, a file-sharing service, to showcase samples of stolen data.(Citation: ElecticIQ Buyukkaya_ShinyHunters_Sept2025) ", "external_references": [{"description": "Büyükkaya, A. (2025, September 22). ShinyHunters Calling: Financially Motivated Data Extortion Group Targeting Enterprise Cloud Applications. Retrieved May 18, 2026.", "source_name": "ElecticIQ Buyukkaya_ShinyHunters_Sept2025", "url": "https://blog.eclecticiq.com/shinyhunters-calling-financially-motivated-data-extortion-group-targeting-enterprise-cloud-applications"}], "id": "relationship--58fd919a-44e2-46d5-ac18-bb327e80b3ff", "modified": "2026-07-31T18:47:58.748Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--5e30362d-935b-4b1c-8bf2-96c7b7b7e299", "spec_version": "2.1", "target_ref": "attack-pattern--40597f16-0963-4249-bf4c-ac93b7fb9807", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24571', 0, 87, '09-mitre-attack', 'retrieved', '9CA89B440507992FB0B6676CEF5651BA1B3090AD1AA7B4611BC06E399ED00A0F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
