VALUES ('doc-09-mitre-attack-p0-24573', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-29T18:56:01.584Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ShinyHunters](https://attack.mitre.org/groups/G1057) has exploited vulnerabilities in the target company’s GitHub repository source code to enable more complex follow-on third-party or supply chain attacks.(Citation: Intel471_SH_Aug2021)", "external_references": [{"description": "Intel 471. (2021, August 23). Here’s how to guard your enterprise against ShinyHunters. Retrieved July 29, 2026.", "source_name": "Intel471_SH_Aug2021", "url": "https://www.intel471.com/blog/shinyhunters-data-breach-mitre-attack"}], "id": "relationship--630900fe-588f-44af-8f46-f722c503b6fd", "modified": "2026-07-31T18:47:58.776Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--5e30362d-935b-4b1c-8bf2-96c7b7b7e299", "spec_version": "2.1", "target_ref": "attack-pattern--be2dcee9-a7a7-4e38-afd6-21b31ecc3d63", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24573', 0, 75, '09-mitre-attack', 'retrieved', '7E90D1DE851BE7ED6D7A60809A8F0A8F44FE16D536D6478270BDB6A8040A8540', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
