VALUES ('doc-09-mitre-attack-p0-24574', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-29T18:54:22.667Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ShinyHunters](https://attack.mitre.org/groups/G1057) has stolen valid OAuth credentials from DevOps personnel or a company GitHub repository.(Citation: Intel471_SH_Aug2021) Additionally, [ShinyHunters](https://attack.mitre.org/groups/G1057) has stolen application access tokens to access cloud services and to bypass authentication mechanisms.(Citation: SOCRadar_ShinyHunters_Mar2024) ", "external_references": [{"description": "Intel 471. (2021, August 23). Here’s how to guard your enterprise against ShinyHunters. Retrieved July 29, 2026.", "source_name": "Intel471_SH_Aug2021", "url": "https://www.intel471.com/blog/shinyhunters-data-breach-mitre-attack"}, {"description": "SOCRadar. (2024, March 18). Dark Web Profile: ShinyHunters. Retrieved May 18, 2026.", "source_name": "SOCRadar_ShinyHunters_Mar2024", "url": "https://socradar.io/dark-web-profile-shinyhunters/"}], "id": "relationship--68501418-9bf5-4f7f-a29e-0c11111bf791", "modified": "2026-07-31T18:47:58.803Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--5e30362d-935b-4b1c-8bf2-96c7b7b7e299", "spec_version": "2.1", "target_ref": "attack-pattern--890c9858-598c-401d-a4d5-c67ebcdd703a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24574', 0, 102, '09-mitre-attack', 'retrieved', 'BCA3843C1ACBE5A780068EDDB6490B690B82FB2E2A907D4A8CBE7229013C2D7C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
