VALUES ('doc-09-mitre-attack-p0-24580', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-29T18:52:57.733Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ShinyHunters](https://attack.mitre.org/groups/G1057) has used valid cloud accounts to gain initial access or to escalate privileges within cloud environments.(Citation: SOCRadar_ShinyHunters_Mar2024) Additionally, [ShinyHunters](https://attack.mitre.org/groups/G1057) has also used valid credentials from public repositories to include access keys to gain access to the victim organization’s AWS environment.(Citation: Unit42KelleyVaya_BlingLibra_Aug2024)(Citation: Intel471_SH_Aug2021)", "external_references": [{"description": "Intel 471. (2021, August 23). Here’s how to guard your enterprise against ShinyHunters. Retrieved July 29, 2026.", "source_name": "Intel471_SH_Aug2021", "url": "https://www.intel471.com/blog/shinyhunters-data-breach-mitre-attack"}, {"description": "Kelley, M., Vaya, C. (2024, August 23). Bling Libra’s Tactical Evolution: The Threat Actor Group Behind ShinyHunters Ransomware. Retrieved May 18, 2026.", "source_name": "Unit42KelleyVaya_BlingLibra_Aug2024", "url": "https://unit42.paloaltonetworks.com/shinyhunters-ransomware-extortion/"}, {"description": "SOCRadar. (2024, March 18). Dark Web Profile: ShinyHunters. Retrieved May 18, 2026.", "source_name": "SOCRadar_ShinyHunters_Mar2024", "url": "https://socradar.io/dark-web-profile-shinyhunters/"}], "id": "relationship--8afa26f2-4df2-4d97-b2c8-747683443803", "modified": "2026-07-31T18:47:58.899Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--5e30362d-935b-4b1c-8bf2-96c7b7b7e299", "spec_version": "2.1", "target_ref": "attack-pattern--f232fa7a-025c-4d43-abc7-318e81a73d65", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_b