VALUES ('doc-09-mitre-attack-p0-24589', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-29T15:55:07.096Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ShinyHunters](https://attack.mitre.org/groups/G1057) has called or sent text messages or emails to employees of victim organizations to demand payment in Bitcoin within 72 hours. Email addresses used in extortion activities include shinycorp@tuta[.]com, shinygroup@tuta[.]com, shinycorp@tutanota[.]com, and shinygroup@onionmail[.]com.(Citation: Google Salesforce JUN 2025)(Citation: Mandiant_SHDataTheft_Jan2026)(Citation: FBI_SHLMS_May2026)(Citation: Intel471_SH_Aug2021)(Citation: Unit42KelleyVaya_BlingLibra_Aug2024)(Citation: SOCRadar_ShinyHunters_Mar2024)(Citation: ElecticIQ Buyukkaya_ShinyHunters_Sept2025) ", "external_references": [{"description": "Büyükkaya, A. (2025, September 22). ShinyHunters Calling: Financially Motivated Data Extortion Group Targeting Enterprise Cloud Applications. Retrieved May 18, 2026.", "source_name": "ElecticIQ Buyukkaya_ShinyHunters_Sept2025", "url": "https://blog.eclecticiq.com/shinyhunters-calling-financially-motivated-data-extortion-group-targeting-enterprise-cloud-applications"}, {"description": "Federal Bureau of Investigation. (2026, May 15). ShinyHunters: Cyber Criminal Group Attacks Learning Management System. Retrieved July 1, 2026.", "source_name": "FBI_SHLMS_May2026", "url": "https://www.ic3.gov/PSA/2026/PSA260515"}, {"description": "Google Threat Intelligence Group. (2025, June 4). The Cost of a Call: From Voice Phishing to Data Extortion. Retrieved October 22, 2025.", "source_name": "Google Salesforce JUN 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/voice-phishing-data-extortion"}, {"description": "Intel 471. (2021, August 23). Here’s how to guard your enterprise against ShinyHunters. Retrieved July 29, 2026.", "source_name": "Intel471_SH_Aug2021", "url": "https://www.intel471.com/blog/shinyhunters-data-breach-mitre-attack"}, {"description": "Kelley, M., Vaya, C. (2024, August 23). Bling Libra’s Tactical Evolution: The Threat Actor Group Behind ShinyHunters Ransomware. Retrieved May 18, 2026.", "source_name": "Unit42KelleyVaya_BlingLibra_Aug2024", "url": "https://unit42.paloaltonetworks.com/shinyhunters-ransomware-extortion/"}, {"description": "Mandiant. (2026, January 30). Vishing for Access: Tracking the Expansion of ShinyHunters-Branded SaaS Data Theft. Retrieved June 16, 2026.", "source_name": "Mandiant_SHDataTheft_Jan2026", "url": "https://cloud.google.com/blog/topics/threat-intelligence/expansion-shinyhunters-saas-data-theft"}, {"description": "SOCRadar. (2024, March 18). Dark Web Profile: ShinyHunters. Retrieved May 18, 2026.", "source_name": "SOCRadar_ShinyHunters_Mar2024", "url": "https://socradar.io/dark-web-profile-shinyhunters/"}], "id": "relationship--adae2782-ce69-4587-bfb0-2417ee44e0fa", "modified": "2026-07-31T18:47:59.015Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--5e30362d-935b-4b1c-8bf2-96c7b7b7e299", "spec_version": "2.1", "target_ref": "attack-pattern--851e071f-208d-4c79-adc6-5974c85c78f3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24589', 0, 246, '09-mitre-attack', 'retrieved', '65AA5037C57675E179C79F68BA0322626DD024E91C6E9B64A06F19EE5A860325', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
