VALUES ('doc-09-mitre-attack-p0-24590', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-29T18:59:51.561Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ShinyHunters](https://attack.mitre.org/groups/G1057) has used Amazon Simple Storage Service (S3) Browser and WinSCP to collect information on S3 bucket configurations.(Citation: Unit42KelleyVaya_BlingLibra_Aug2024)(Citation: SOCRadar_ShinyHunters_Mar2024) ", "external_references": [{"description": "Kelley, M., Vaya, C. (2024, August 23). Bling Libra’s Tactical Evolution: The Threat Actor Group Behind ShinyHunters Ransomware. Retrieved May 18, 2026.", "source_name": "Unit42KelleyVaya_BlingLibra_Aug2024", "url": "https://unit42.paloaltonetworks.com/shinyhunters-ransomware-extortion/"}, {"description": "SOCRadar. (2024, March 18). Dark Web Profile: ShinyHunters. Retrieved May 18, 2026.", "source_name": "SOCRadar_ShinyHunters_Mar2024", "url": "https://socradar.io/dark-web-profile-shinyhunters/"}], "id": "relationship--b04004a8-57bd-4245-813b-9e64ede24a18", "modified": "2026-07-31T18:47:59.030Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--5e30362d-935b-4b1c-8bf2-96c7b7b7e299", "spec_version": "2.1", "target_ref": "attack-pattern--57a3d31a-d04f-4663-b2da-7df8ec3f8c9d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24590', 0, 95, '09-mitre-attack', 'retrieved', '9CD4EDA58F69C8C2791B12AC1FEA59335CE38C3A7025F94E1194B17072987ECD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
