VALUES ('doc-09-mitre-attack-p0-24591', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-29T18:45:08.315Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ShinyHunters](https://attack.mitre.org/groups/G1057) has enumerated the internal subnet using ` cat /etc/hosts | grep -E \"[redacted_victim_string]\"`.(Citation: Google_SHOracle_Jun2026) ", "external_references": [{"description": "Mandiant, Google Threat Intelligence Group. (2026, June 11). ShinyHunters Targets Education Sector with Oracle PeopleSoft Exploit. Retrieved June 11, 2026.", "source_name": "Google_SHOracle_Jun2026", "url": "https://cloud.google.com/blog/topics/threat-intelligence/shinyhunters-targets-education-sector-oracle-exploit"}], "id": "relationship--bae9c6ec-2d33-418b-b7db-8b99af22e32f", "modified": "2026-07-31T18:47:59.040Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--5e30362d-935b-4b1c-8bf2-96c7b7b7e299", "spec_version": "2.1", "target_ref": "attack-pattern--e358d692-23c0-4a31-9eb6-ecc13a8d7735", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24591', 0, 71, '09-mitre-attack', 'retrieved', '2977701F521B3313C3C1C14383AC2D0B8F65D16BEAD085A0802FF38CBA985F7A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
