VALUES ('doc-09-mitre-attack-p0-24600', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-29T15:56:46.679Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ShinyHunters](https://attack.mitre.org/groups/G1057) has established clearnet and Tor data leak sites (DLS) including one named “SHINYHUNTERS” for the exfiltration and posting of stolen data.(Citation: Mandiant_SHDataTheft_Jan2026)(Citation: FBI_SHLMS_May2026) Additionally, [ShinyHunters](https://attack.mitre.org/groups/G1057) has registered domains that mimic legitimate Microsoft Azure NetApp Files endpoints, such as azurenetfiles[.]net, and legitimate Okta SSO login pages, such as trial-6857053.okta[.]com.(Citation: Google_SHOracle_Jun2026)(Citation: ElecticIQ Buyukkaya_ShinyHunters_Sept2025) ", "external_references": [{"description": "Büyükkaya, A. (2025, September 22). ShinyHunters Calling: Financially Motivated Data Extortion Group Targeting Enterprise Cloud Applications. Retrieved May 18, 2026.", "source_name": "ElecticIQ Buyukkaya_ShinyHunters_Sept2025", "url": "https://blog.eclecticiq.com/shinyhunters-calling-financially-motivated-data-extortion-group-targeting-enterprise-cloud-applications"}, {"description": "Federal Bureau of Investigation. (2026, May 15). ShinyHunters: Cyber Criminal Group Attacks Learning Management System. Retrieved July 1, 2026.", "source_name": "FBI_SHLMS_May2026", "url": "https://www.ic3.gov/PSA/2026/PSA260515"}, {"description": "Mandiant, Google Threat Intelligence Group. (2026, June 11). ShinyHunters Targets Education Sector with Oracle PeopleSoft Exploit. Retrieved June 11, 2026.", "source_name": "Google_SHOracle_Jun2026", "url": "https://cloud.google.com/blog/topics/threat-intelligence/shinyhunters-targets-education-sector-oracle-exploit"}, {"description": "Mandiant. (2026, January 30). Vishing for Access: Tracking the Expansion of ShinyHunters-Branded SaaS Data Theft. Retrieved June 16, 2026.", "source_name": "Mandiant_SHDataTheft_Jan2026", "url": "https://cloud.google.com/blog/topics/threat-intelligence/expansion-shinyhunters-saas-data-theft"}], "id": "relationship--df55f1d1-f7a0-4e93-af6a-ee4e47d0b809", "modified": "2026-07-31T18:47:59.188Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--5e30362d-935b-4b1c-8bf2-96c7b7b7e299", "spec_version": "2.1", "target_ref": "attack-pattern--40f5caa0-4cb7-4117-89fc-d421bb493df3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24600', 0, 182, '09-mitre-attack', 'retrieved', '639A58442AFA00651F78765C67A08DACF62C209F49BA15BD8B4C0A66023218CD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
