VALUES ('doc-09-mitre-attack-p0-24608', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-30T21:24:04.534Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kali365](https://attack.mitre.org/software/S9044) has dynamically generated legitimate device codes that displays on the victims screen alongside instructions to copy and paste the device code to initiate and complete a successful authentication process.(Citation: Artic Wolf Labs Kali365 Device Code April 2026)(Citation: Artic Wolf Kali365 Device Code OAuth June 2026)(Citation: FBI IC3 Alert I-052126 Kali365 May 2026)(Citation: Huntress Kali365 Device Code June 2026)(Citation: SpyCloud Kali365 June 2026)", "external_references": [{"description": "Artic Wolf Labs. (2026, April 24). Token Bingo: Don’t Let Your Code be the Winner. Retrieved July 30, 2026.", "source_name": "Artic Wolf Labs Kali365 Device Code April 2026", "url": "https://arcticwolf.com/resources/blog/token-bingo-dont-let-your-code-be-the-winner/"}, {"description": "Artic Wolf Labs. (2026, June 2). Retrieved July 30, 2026.", "source_name": "Artic Wolf Kali365 Device Code OAuth June 2026", "url": "https://arcticwolf.com/resources/blog/kali365-expands-into-aws-microsoft-okta-xerox-max-messenger/"}, {"description": "Federal Bureau of Investigation. (2026, May 21). Alert Number: I-052126-PSA: Kali365 Phishing-as-a-Service Kit Hijacks Microsoft 365 Access Tokens. Retrieved July 30, 2026.", "source_name": "FBI IC3 Alert I-052126 Kali365 May 2026", "url": "https://www.ic3.gov/PSA/2026/PSA260521"}, {"description": "Tanner Flip. (2026, June 11). Hook, Line, and Token: Anatomy of the Kali365 / Octopi365 Phishing-as-a-Service Kit. Retrieved July 30, 2026.", "source_name": "Huntress Kali365 Device Code June 2026", "url": "https://www.huntress.com/blog/kali365-device-code-phishing-kit"}, {"description": "Trevor Hilligoss. (2026, June 11). Kali365: Anatomy of a Microsoft 365 Phishing-as-a-Service Kit – From Telegram Hype to FBI Takedown Theater. Retrieved July 30, 2026.", "source_name": "SpyCloud Kali365 June 2026", "url": "https://spycloud.com/blog/kali365-anatomy-of-a-microsoft365-phishing-as-a-service-kit/"}], "id": "relationship--f0fd6b35-3bde-4f29-8a16-a3b7e1794dc5", "modified": "2026-07-30T21:24:04.534Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f5a56c26-e192-489d-a77e-a8b38fd70eee", "spec_version": "2.1", "target_ref": "attack-pattern--e261a979-f354-41a8-963e-6cadac27c4bf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24608', 0, 243, '09-mitre-attack', 'retrieved', '853C7DCA91DF83CE8B1A1E07DB1E72F17CC3DB4A46904A639F828240029CBBC5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
