VALUES ('doc-09-mitre-attack-p0-24609', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-30T21:26:31.387Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kali365](https://attack.mitre.org/software/S9044) has created obfuscated phishing landing pages that act as an adversary in the middle infrastructure that intercepts communications between the victim host and legitimate services to steal credentials and user sessions.(Citation: Artic Wolf Labs Kali365 Device Code April 2026)(Citation: Artic Wolf Kali365 Device Code OAuth June 2026)(Citation: SpyCloud Kali365 June 2026)", "external_references": [{"description": "Artic Wolf Labs. (2026, April 24). Token Bingo: Don’t Let Your Code be the Winner. Retrieved July 30, 2026.", "source_name": "Artic Wolf Labs Kali365 Device Code April 2026", "url": "https://arcticwolf.com/resources/blog/token-bingo-dont-let-your-code-be-the-winner/"}, {"description": "Artic Wolf Labs. (2026, June 2). Retrieved July 30, 2026.", "source_name": "Artic Wolf Kali365 Device Code OAuth June 2026", "url": "https://arcticwolf.com/resources/blog/kali365-expands-into-aws-microsoft-okta-xerox-max-messenger/"}, {"description": "Trevor Hilligoss. (2026, June 11). Kali365: Anatomy of a Microsoft 365 Phishing-as-a-Service Kit – From Telegram Hype to FBI Takedown Theater. Retrieved July 30, 2026.", "source_name": "SpyCloud Kali365 June 2026", "url": "https://spycloud.com/blog/kali365-anatomy-of-a-microsoft365-phishing-as-a-service-kit/"}], "id": "relationship--63def7ec-93fd-4d42-b27d-d7147a937524", "modified": "2026-07-30T21:26:31.387Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f5a56c26-e192-489d-a77e-a8b38fd70eee", "spec_version": "2.1", "target_ref": "attack-pattern--035bb001-ab69-4a0b-9f6c-2de8b09e1b9d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated