VALUES ('doc-09-mitre-attack-p0-24616', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-30T21:48:51.366Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kali365](https://attack.mitre.org/software/S9044) has utilized an Exchange Admin module that captured admin tokens to create rogue mailbox connectors and change mail-flow rules.(Citation: Huntress Kali365 Device Code June 2026)", "external_references": [{"description": "Tanner Flip. (2026, June 11). Hook, Line, and Token: Anatomy of the Kali365 / Octopi365 Phishing-as-a-Service Kit. Retrieved July 30, 2026.", "source_name": "Huntress Kali365 Device Code June 2026", "url": "https://www.huntress.com/blog/kali365-device-code-phishing-kit"}], "id": "relationship--c80bc262-246d-40a1-9216-7b18b50fb6e6", "modified": "2026-07-30T21:48:51.366Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f5a56c26-e192-489d-a77e-a8b38fd70eee", "spec_version": "2.1", "target_ref": "attack-pattern--f005e783-57d4-4837-88ad-dbe7faee1c51", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24616', 0, 87, '09-mitre-attack', 'retrieved', '0D4840BC5B0C670465358AD2C68C15E33E7C62C06E55D7D26AFBF2CE83821865', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
