VALUES ('doc-09-mitre-attack-p0-24617', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-30T21:42:12.728Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kali365](https://attack.mitre.org/software/S9044) has executed JavaScript within victims'' browsers through a React frontend that detects browser sessions to evade automated analysis, auto-copies actor-generated device codes to the victim''s clipboard, and polls the actor''s C2 infrastructure every three seconds to confirm when OAuth token capture has completed..(Citation: Artic Wolf Labs Kali365 Device Code April 2026)(Citation: Artic Wolf Kali365 Device Code OAuth June 2026)(Citation: Huntress Kali365 Device Code June 2026)", "external_references": [{"description": "Artic Wolf Labs. (2026, April 24). Token Bingo: Don’t Let Your Code be the Winner. Retrieved July 30, 2026.", "source_name": "Artic Wolf Labs Kali365 Device Code April 2026", "url": "https://arcticwolf.com/resources/blog/token-bingo-dont-let-your-code-be-the-winner/"}, {"description": "Artic Wolf Labs. (2026, June 2). Retrieved July 30, 2026.", "source_name": "Artic Wolf Kali365 Device Code OAuth June 2026", "url": "https://arcticwolf.com/resources/blog/kali365-expands-into-aws-microsoft-okta-xerox-max-messenger/"}, {"description": "Tanner Flip. (2026, June 11). Hook, Line, and Token: Anatomy of the Kali365 / Octopi365 Phishing-as-a-Service Kit. Retrieved July 30, 2026.", "source_name": "Huntress Kali365 Device Code June 2026", "url": "https://www.huntress.com/blog/kali365-device-code-phishing-kit"}], "id": "relationship--cfb02b3d-c902-480f-a579-06ac4ba0c5a4", "modified": "2026-07-31T02:57:02.370Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f5a56c26-e192-489d-a77e-a8b38fd70eee", "spec_version": "2.1", "target_ref": "attack-pattern--0f4a0c76-ab2d-4cb0-85d3-3f0efb8cba0d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24617', 0, 180, '09-mitre-attack', 'retrieved', '99369F0923F9AED09944B5D2979C1A89098B84CF40B6CAA93F909FFCC207D78A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
