VALUES ('doc-09-mitre-attack-p0-24618', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-30T21:55:18.692Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kali365](https://attack.mitre.org/software/S9044)''s desktop client has made Microsoft Graph API calls using the distinct User-Agent string `kali365-live/1.0.0` to access victim mailboxes and enumerate account data following OAuth token capture.(Citation: Artic Wolf Labs Kali365 Device Code April 2026)", "external_references": [{"description": "Artic Wolf Labs. (2026, April 24). Token Bingo: Don’t Let Your Code be the Winner. Retrieved July 30, 2026.", "source_name": "Artic Wolf Labs Kali365 Device Code April 2026", "url": "https://arcticwolf.com/resources/blog/token-bingo-dont-let-your-code-be-the-winner/"}], "id": "relationship--e175fff5-82a9-49dc-842a-a24548d5960d", "modified": "2026-07-31T03:16:46.015Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f5a56c26-e192-489d-a77e-a8b38fd70eee", "spec_version": "2.1", "target_ref": "attack-pattern--df8b2a25-8bdf-4856-953c-a04372b1c161", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24618', 0, 96, '09-mitre-attack', 'retrieved', '5E405375E47C222380C7FB5C97E8B93CA94C7AB14FA43F795186936A081F6C7E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
